import os, json, datetime, numpy as np

def utc_now(): return datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
def ensure_dir(p): os.makedirs(p, exist_ok=True)
def read_json(p):
    with open(p, "r", encoding="utf-8") as f: return json.load(f)
def append_status(p, s):
    ensure_dir(os.path.dirname(p))
    with open(p, "a", encoding="utf-8") as f: f.write(s)

def detect_pairs(data):
    # Return dict {(i,j): slack} with i<j
    candidates = []
    if isinstance(data, dict):
        for key in ["pairs_sorted", "pairs", "pairs_slacks_sorted", "pair_slacks_sorted", "pairs_all"]:
            if key in data and isinstance(data[key], list):
                candidates = data[key]; break
    if not candidates and isinstance(data, list):
        candidates = data
    if not candidates and isinstance(data, dict):
        for v in data.values():
            if isinstance(v, list) and v and isinstance(v[0], (list, tuple)) and len(v[0]) >= 3:
                candidates = v; break
    pairs = {}
    for row in candidates:
        if not isinstance(row, (list, tuple)) or len(row) < 3: continue
        i, j, s = int(row[0]), int(row[1]), float(row[2])
        if i == j: continue
        if i > j: i, j = j, i
        pairs[(i, j)] = s
    return pairs

def load_pairs(path):
    if not os.path.exists(path): return None
    try: return detect_pairs(read_json(path))
    except Exception: return None

def rank_array(x):
    idx = np.argsort(x, kind="mergesort")
    ranks = np.empty_like(idx, dtype=float); ranks[idx] = np.arange(1, len(x)+1, dtype=float)
    xs = x[idx]; n = len(x); a = 0
    while a < n:
        b = a + 1
        while b < n and xs[b] == xs[a]: b += 1
        if b - a > 1:
            avg = (a + 1 + b) / 2.0
            ranks[idx[a:b]] = avg
        a = b
    return ranks

def spearman_rho(a, b):
    if len(a) == 0: return None
    ra = rank_array(a.astype(float)); rb = rank_array(b.astype(float))
    a0 = ra - ra.mean(); b0 = rb - rb.mean()
    denom = np.sqrt((a0*a0).sum() * (b0*b0).sum())
    return float((a0*b0).sum() / denom) if denom > 0 else None

def jaccard(S1, S2):
    if not S1 and not S2: return 1.0
    inter = len(S1 & S2); uni = len(S1 | S2)
    return inter/uni if uni else 0.0

def topk_set(pairs_dict, K):
    items = list(pairs_dict.items())
    items.sort(key=lambda kv: (kv[1], kv[0][0], kv[0][1]))
    return set([ij for ij, _ in items[:min(K, len(items))]])

def construct_packing():
    ts = utc_now()
    shared = os.path.join("storage", "shared", "appxE_contribs")
    out_root = os.path.join("storage", "noesis", "nmap")
    results_dir = os.path.join(out_root, "results"); ensure_dir(results_dir)
    status_path = os.path.join(out_root, "AGGREGATOR_v2_1_STATUS.md")

    # Noesis reference
    noe_path = os.path.join(shared, "noesis_III_eval1127_pair_slacks_all.json")
    noesis_pairs = load_pairs(noe_path)

    # Quest candidates (multi-name support)
    quest_candidates = [
        os.path.join(shared, "quest_II_latest_packing_slacks_clearances.json"),
        os.path.join(shared, "quest_II_latest_slacks.json"),
        os.path.join(shared, "latest_slacks.json"),
    ]
    quest_path = next((p for p in quest_candidates if os.path.exists(p)), None)
    quest_pairs = load_pairs(quest_path) if quest_path else None

    res = {
        "version": "v2.1",
        "timestamp_utc": ts,
        "noesis_source": noe_path if os.path.exists(noe_path) else None,
        "quest_source": quest_path
    }

    if noesis_pairs is None:
        append_status(status_path, f"\n[{ts}] ERROR: Noesis III pair slacks not found at {noe_path}\n")
    elif quest_pairs is None:
        append_status(status_path, f"\n[{ts}] INFO: Quest latest pair slacks not present yet under {quest_candidates}\n")
    else:
        keys = sorted(set(noesis_pairs.keys()) & set(quest_pairs.keys()))
        x = np.array([noesis_pairs[k] for k in keys], dtype=float)
        y = np.array([quest_pairs[k] for k in keys], dtype=float)
        rho = spearman_rho(x, y)
        N25_noe = topk_set(noesis_pairs, 25); N15_noe = topk_set(noesis_pairs, 15)
        Q25_que = topk_set(quest_pairs, 25); Q15_que = topk_set(quest_pairs, 15)
        j25 = jaccard(N25_noe, Q25_que); j15 = jaccard(N15_noe, Q15_que)
        res.update({"pair_count": len(keys), "spearman_rho": rho, "jaccard_topk_25": j25, "jaccard_topk_15": j15})
        rho_str = f"{rho:.6f}" if rho is not None else "nan"
        append_status(status_path, f"\n[{ts}] Rank‑corr vs Quest latest: rho={rho_str}, J@25={j25:.6f}, J@15={j15:.6f}\n")

    out_path = os.path.join(results_dir, "noesisIII_vs_quest_latest_pair_slack_rankcorr.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=2, sort_keys=True)

    # Return a trivial valid packing
    centers, radii = [], []
    r = 0.06
    for i in range(5):
        for j in range(6):
            if len(centers) < 26:
                centers.append([0.1 + 0.2*i, 0.1 + 0.15*j]); radii.append(r)
    return np.array(centers, float), np.array(radii, float)
